const express = require('express');
const router = express.Router();
const db = require('../db');

router.post('/complimentary', (req, res) => {
    // Validate required fields
    const { employeeId, startDate, endDate } = req.body;
    if (!employeeId || !startDate || !endDate) {
        return res.status(400).json({ message: 'Missing required fields: employeeId, startDate, endDate' });
    }

    // Retrieve the user's role from the database
    db.query('SELECT role FROM Employee WHERE id = ?', [req.headers.userid], (err, result) => {
        if (err) {
            console.log(err);
            return res.status(500).json({ message: 'Error retrieving user role.' });
        }

        if (result.length === 0) {
            return res.status(404).json({ message: 'Employee not found.' });
        }

        const userRole = result[0].role;

        // Retrieve the role's permissions
        db.query('SELECT permissions FROM Roles WHERE name = ?', [userRole], (err, result) => {
            if (err) {
                console.log(err);
                return res.status(500).json({ message: 'Error retrieving role permissions.' });
            }

            if (result.length === 0) {
                return res.status(404).json({ message: 'Role not found.' });
            }

            const permissions = result[0].permissions;
            const hasPermission = permissions.includes('add_complimentary');

            if (!hasPermission) {
                return res.status(401).json({ message: 'Unauthorized. Your role does not have the permission to add complimentary leaves.' });
            }

            // Validate date range
            const start = new Date(startDate);
            const end = new Date(endDate);
            if (isNaN(start) || isNaN(end) || start > end) {
                return res.status(400).json({ message: 'Invalid date range. Start date must be before end date.' });
            }

            // Insert the complimentary leave into the database
            const insertQuery = `
                INSERT INTO ComplimentaryLeaves (employeeId, startDate, endDate, createdById, createdAt)
                VALUES (?, ?, ?, ?, NOW())
            `;
            db.query(insertQuery, [employeeId, startDate, endDate, req.headers.userid], (err, result) => {
                if (err) {
                    console.log(err);
                    return res.status(500).json({ message: 'Error adding complimentary leave.' });
                }

                return res.status(201).json({
                    message: 'Complimentary leave added successfully.',
                    id: result.insertId
                });
            });
        });
    });
});
